<script lang="ts">
  import { onMount } from 'svelte'
  import { api } from '$lib/api'
  let settings: any = { publicSignup: true, maxFormsPerUser: 20, maxSubmissionsPerForm: 5000, maintenanceMode: false }; let notice = ''; let error = ''; let loading = false
  onMount(() => { api<{ data: any }>('/admin/settings').then((result) => settings = result.data).catch((reason: any) => error = reason.message) })
  async function save() { loading = true; notice = ''; error = ''; try { const result = await api<{ data: any }>('/admin/settings', { method: 'PATCH', body: JSON.stringify(settings) }); settings = result.data; notice = 'Platform settings saved.' } catch (reason: any) { error = reason.message } finally { loading = false } }
</script>
<main class="admin-content"><div class="page-title"><div><span class="kicker">PLATFORM CONFIGURATION</span><h1>Settings</h1><p>Manage access policy, usage limits, and service availability.</p></div></div>{#if error}<div class="notice error">{error}</div>{/if}{#if notice}<div class="notice success">{notice}</div>{/if}<section class="panel settings-panel"><h2>Account creation</h2><label class="setting-row"><span><b>Public signup</b><small>Allow visitors to create a Forms workspace.</small></span><input type="checkbox" bind:checked={settings.publicSignup}/></label><label class="setting-row"><span><b>Maintenance mode</b><small>Pause public form submissions while maintenance is active.</small></span><input type="checkbox" bind:checked={settings.maintenanceMode}/></label><h2>Usage limits</h2><label class="field-label">Maximum active forms per user<input type="number" min="1" max="500" bind:value={settings.maxFormsPerUser}/></label><label class="field-label">Maximum responses per form<input type="number" min="1" max="1000000" bind:value={settings.maxSubmissionsPerForm}/></label><button class="primary-button" onclick={save} disabled={loading}>{loading ? 'Saving…' : 'Save settings'} <span>→</span></button></section></main>
